-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := 'a2af589f-657c-44a8-ae85-646363a2fcfd';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Who You Are Actually Marketing To', 'The existing lessons cover SEO, Facebook ads and content — the tactics. This one covers the question every one of those tactics assumes you have already answered, and most beginners have not.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Finding Your Target Audience', 'HubSpot''s six-step framework for working out who your marketing is for, using evidence rather than assumption. About 12 minutes.', 'https://www.youtube.com/watch?v=6mugRyElbd0', 1,
      array['Define an audience narrowly enough to make marketing decisions', 'Use data you already have instead of guessing', 'Explain why marketing to everyone reaches no one'],
      'Ask a beginner who their customer is and the answer is usually "anyone who needs this". That answer makes every later decision impossible. Which platform? What tone? What price? What objection do you answer first? All of it depends on knowing who you are talking to.

WHY NARROW BEATS BROAD, and this is genuinely counter-intuitive when you are starting and want every customer you can get: a message aimed at everyone is generic, and generic messages get ignored. "Affordable web design" says nothing. "Websites for Nairobi salons that want bookings by WhatsApp" is instantly clear to exactly the people who need it — and the ones it excludes were never going to buy anyway.

WHERE THE EVIDENCE COMES FROM, in order of how much it is worth:
- YOUR EXISTING CUSTOMERS. Who has already paid you, and what did they have in common? This is the most reliable data you will ever get, and it is free.
- SALES AND SUPPORT CONVERSATIONS. What do people ask before buying? Their questions are the objections your marketing must answer.
- ANALYTICS. Who actually visits, from where, on what device.
- COMPETITORS'' AUDIENCES — who is engaging with them, and what those people complain about in the comments.
- SURVEYS AND INTERVIEWS, useful but remember people report what they think they should say.

WHAT TO WRITE DOWN, and keep it to things that change a decision: what problem they are trying to solve, what they have already tried, what would stop them buying, where they spend time online, and what they can afford. Age and gender are usually far less useful than beginners assume — two 30-year-olds in Nairobi can have nothing in common as customers.

FOR THIS MARKET SPECIFICALLY: think about how your audience gets online and pays. Most are on phones with metered data, many prefer to finish a conversation on WhatsApp rather than a form, and price sensitivity is real. An audience definition that ignores those facts will produce marketing that looks good and does not convert.

AND REVISIT IT. The audience you imagined at the start and the audience that actually pays you after six months are rarely the same. Let the paying one win.',
      'Write one paragraph describing your customer, using the fields above and no demographics unless they genuinely change a decision. Then test it: name three real people or businesses who fit, and one who does not. If you cannot name three, the definition is a guess — go and have two conversations before writing any more marketing.',
      '[{"question":"Why does defining your audience narrowly usually outperform aiming at everyone?","options":["A message for everyone is generic and gets ignored; a specific one is instantly clear to the people who need it","Narrow audiences cost less to reach on every platform","Platforms rank narrow campaigns more highly","It reduces the number of competitors"],"correct_index":0},{"question":"What is the most reliable source of evidence about your audience?","options":["The customers who have already paid you, and what they had in common","A survey of your social media followers","Industry reports about your sector","What competitors say about their customers"],"correct_index":0}]'::jsonb),
    (v_m1, 'Turning That Into a Buyer Persona You Can Use', 'HubSpot on building a buyer persona — the short written profile that keeps every marketing decision consistent. Under 6 minutes.', 'https://www.youtube.com/watch?v=v6EWN4EjHM0', 2,
      array['Write a persona short enough that people actually use it', 'Base each detail on evidence rather than imagination', 'Use a persona to settle an argument about a marketing decision'],
      'A persona is the previous lesson written down as one specific person, so that everyone making decisions is picturing the same human being.

WHAT MAKES A PERSONA USEFUL RATHER THAN DECORATIVE: every line must be something that changes what you would do. A stock photo and an invented name change nothing. "Checks Instagram at night on a phone, will not fill in a form longer than three fields, needs to see a price before enquiring" changes your landing page, your ad schedule and your copy.

THE FIELDS WORTH HAVING:
- The GOAL they are trying to achieve, in their own words
- The OBSTACLE stopping them
- What they have TRIED already, and why it did not work
- Their OBJECTION — the specific reason they would not buy from you
- Where they spend time and how they prefer to be contacted
- What they can realistically pay

USE THEIR LANGUAGE, NOT YOURS. Write down the actual phrases customers use, from messages and comments, and put those phrases in your marketing. A customer searching "cheap website for my shop" will not click an advert for "bespoke digital presence solutions". This single habit improves copy more than any writing technique.

ONE PERSONA IS ENOUGH TO START. Beginners build five and use none. Build the one who represents your best existing customers, and add another only when you can point to a real group your first persona genuinely does not cover.

THE TEST OF A GOOD PERSONA is that it settles arguments. When someone asks whether to run a TikTok campaign, the persona answers it — either she is there or she is not. If your persona cannot settle that, it is too vague to be worth having.

AND KEEP IT TO ONE PAGE. A twelve-page persona document is a project that got confused with a tool. One page, visible, revised when the evidence changes.',
      'Write a one-page persona for your best existing customer type, with every field traceable to something you actually observed — a message they sent, a question they asked, an analytics number. Then use it: take one real marketing decision you are unsure about and answer it from the persona. If it cannot answer, note which field was missing and go find that out.',
      '[{"question":"What makes a line in a persona worth including?","options":["It changes a decision you would otherwise make differently","It makes the persona feel like a real person","It matches the industry average for your sector","It can be found in analytics"],"correct_index":0},{"question":"Why write marketing copy in the customer''s own phrases?","options":["They search and click using their words, not your industry terms","It is faster than writing original copy","Search engines penalise technical language","It makes the persona document shorter"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'How People Decide to Buy', 'Nobody sees an advert and buys. Understanding the steps in between is what turns scattered tactics into marketing that compounds.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'The Marketing Funnel', 'HubSpot on building a marketing funnel that works for a small business — the stages between a stranger and a customer. Under 8 minutes.', 'https://www.youtube.com/watch?v=_2H7OlHkv1w', 1,
      array['Name the funnel stages and what a person needs at each', 'Match a tactic to the stage it actually serves', 'Find the stage where you are losing people'],
      'A funnel is just a way of saying: people do not go from never having heard of you to paying you in one step, so stop marketing as if they do.

THE STAGES, and what the person needs at each:

AWARENESS — they have a problem and do not know you exist. They need useful, findable content that answers the question they are asking. SEO, social posts and word of mouth live here. Selling here fails; you have not earned it.

CONSIDERATION — they know you and are weighing options. They need proof: examples of your work, comparisons, prices, answers to the specific objection in their head. Most small businesses have nothing at this stage, which is exactly where they lose people.

DECISION — they are ready and looking for a reason to act now or a reason to hesitate. They need a clear, easy next step, visible pricing and reassurance. A hard-to-find contact button loses sales here that everything upstream paid for.

AFTER THE SALE — the stage everyone forgets, and the cheapest revenue there is. A customer who had a good experience buys again and tells people. Following up costs almost nothing.

THE DIAGNOSTIC THAT MAKES THIS USEFUL: when marketing is not working, find the stage where people drop out rather than doing more of everything.
- Nobody knows you exist → awareness problem, and more discounts will not fix it.
- Plenty of traffic, no enquiries → consideration problem. They are not convinced, usually because there is no proof.
- Enquiries but no sales → decision problem. Price, trust, or a checkout nobody can complete.

MOST BEGINNERS RUN AWARENESS TACTICS AND EXPECT DECISION RESULTS — posting on Instagram and wondering why nobody buys. The post did its job; nothing existed to catch the interest it created.

FOR A KENYAN SMALL BUSINESS, the funnel usually ends in a WhatsApp conversation rather than a checkout, and that is fine — but treat it as a real stage. How fast do you reply? Is there a price list ready to send? Is there a saved answer to the three questions everyone asks? That is decision-stage work, and it is where most sales are won or lost here.',
      'Draw your own funnel on one page and write, under each stage, exactly what you currently have there. Most people find one stage completely empty. Then look at where you actually lose people — traffic with no enquiries, or enquiries with no sales — and build the one missing thing for that stage before adding any new tactic.',
      '[{"question":"You get plenty of website traffic but almost no enquiries. Which stage is failing?","options":["Consideration — there is nothing proving you can do the job","Awareness — not enough people know you exist","Decision — the checkout is too complicated","After the sale — customers are not returning"],"correct_index":0},{"question":"Why does selling hard at the awareness stage usually fail?","options":["The person does not yet know or trust you — that has to be earned first","Platforms restrict promotional content","Awareness content cannot include links","It costs more per impression"],"correct_index":0}]'::jsonb),
    (v_m2, 'Mapping the Journey Your Customer Actually Takes', 'HubSpot on building a customer journey map — following a real person''s path, including the parts that happen outside your marketing. Under 7 minutes.', 'https://www.youtube.com/watch?v=68ZXwI5L4kY', 2,
      array['Map the real steps a customer takes, including offline ones', 'Identify the moments where people give up', 'Fix a journey problem instead of buying more traffic'],
      'A funnel is your view of the process. A journey map is the customer''s view, and the difference matters because the customer''s version includes things your marketing plan does not: asking a friend, losing the link, running out of data, deciding to think about it and forgetting.

HOW TO BUILD ONE: take one real customer — ideally one you can ask — and write every step from first hearing of you to paying, with what they were thinking and feeling at each. Then mark every point where something could go wrong.

WHAT THIS RELIABLY EXPOSES, and it is almost never the thing people expect:
- The form that asks for eight fields on a phone
- The two days it took you to reply, by which time they had bought elsewhere
- The price nobody could find, so they assumed it was expensive
- The link that opened a page that would not load on a slow connection
- The WhatsApp message that arrived at 11pm and got buried

None of those are solved by more advertising, and all of them are cheaper to fix than to out-spend.

THE FEELINGS MATTER as much as the steps. A person who feels unsure at the moment of paying needs reassurance — a clear refund position, a real phone number, a face. A person who feels rushed needs a way to come back later without starting again.

FOR THIS MARKET, three specific journey breakers are worth checking on every map you draw: whether the site is usable on a cheap phone over a slow connection, whether paying is possible in the way people actually pay, and how fast a WhatsApp enquiry gets answered. Those three cause more lost sales here than any messaging problem.

AND WALK IT YOURSELF, on a phone, on mobile data, as if you had never seen it before. Then have someone who has never seen it do the same while you watch in silence. Every uncomfortable pause is money.',
      'Pick one real customer and write out their actual path from first contact to payment, step by step, with what they were thinking at each. Mark every point where they could have given up. Then walk that same path yourself on a phone using mobile data, and time how long it takes from landing to being able to pay. Fix the slowest or most confusing step this week.',
      '[{"question":"What does a customer journey map show that a funnel does not?","options":["The steps and feelings outside your marketing — asking a friend, losing the link, waiting for a reply","The total cost of each advertising channel","Which competitors the customer considered","The lifetime value of the customer"],"correct_index":0},{"question":"Journey mapping shows you lose most people while waiting two days for a reply. What is the right response?","options":["Fix the reply time — no amount of extra advertising compensates for it","Increase the advertising budget to bring in more enquiries","Raise prices to reduce enquiry volume","Add more content at the awareness stage"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
